WITH product_totals AS (SELECT product_id, MAX(quantity) - MIN(quantity) quantity_range, MAX(quantity) max_quantity FROM order_items WHERE unit_price < 310 GROUP BY product_id) SELECT products.brand, products.stock_qty, product_totals.quantity_range, product_totals.max_quantity FROM products INNER JOIN product_totals ON products.id = product_totals.product_id WHERE product_totals.quantity_range > 27;
